df['Date'] = pd.to_datetime(df['Date'], format='%d-%m-%y')
df = df.sort_values('Date').reset_index(drop=True)
df = df[df['Date'] <= '2025-12-31'].copy().reset_index(drop=True)

for p, t, r in kpis['drawdowns']:
    peak_date = str(df.loc[p, 'Date'].date())
    trough_date = str(df.loc[t, 'Date'].date())
    recovery_date = str(df.loc[r, 'Date'].date()) if r < len(df)-1 else 'Ongoing'
    dd_pct = ((df.loc[t, 'Close']/df.loc[p, 'Close'])-1)*100
    dur = (df.loc[t, 'Date'] - df.loc[p, 'Date']).days
