html += """    </table>

    <h3>Regime Transition Probabilities</h3>
    <table>
      <tr><th>From \ To</th><th>Crisis</th><th>High-Vol</th><th>Low-Vol</th><th>Normal</th></tr>
"""

trans = kpis['transitions']
for from_reg in ['Crisis','High-Vol','Low-Vol','Normal']:
    html += f"      <tr><td><strong>{from_reg}</strong></td>"
    for to_reg in ['Crisis','High-Vol','Low-Vol','Normal']:
        val = trans.loc[from_reg, to_reg] if from_reg in trans.index and to_reg in trans.columns else 0
        html += f"<td>{val*100:.1f}%</td>"
    html += "</tr>\n"

html += """    </table>
    <div class="note"><strong>Analyst note:</strong> Crisis and High-Vol states are highly persistent (P(stay) ≈ 87–88%). Low-Vol is the most stable regime. Transitions from Low-Vol to Crisis are rare (~0.05%), but transitions from Normal to High-Vol or Crisis occur with non-trivial probability (~4%).</div>
  </section>

